-- ##########################################################################################
-- SECTION 07/16: APPLY-0180.sql
-- ##########################################################################################
-- APPLY-0180.sql - paste into the Supabase SQL editor (staging first, then production).
-- Trial sign-up flow: every NEW free trial gets the sample data + India defaults (no "own data"
-- choice any more), a server-side welcome flag so the 2-step welcome + tour also show when the
-- e-mail confirm link is opened on another device, and the free-trial owner is not forced
-- through /profile-setup before the welcome.
-- What it touches: organizations gets ONE new nullable column (trial_welcome_pending); 2 new
-- functions (my_trial_welcome_pending, trial_welcome_set); 2 replaced with the same signature
-- (start_self_serve_trial, my_profile_status). No existing row is changed. Paid studios are
-- unaffected. No DROP / DELETE / TRUNCATE. Safe to run twice (the 2nd run changes nothing).
begin;
-- 0180_trial_signup_flow.sql - CANONICAL forward-only.
-- REQUIRES 0041 (my_profile_status), 0116 (_trial_locked), 0119 (start_self_serve_trial),
--          0166 (_is_trial_org, organizations.is_sample_master), 0177 (India trigger on organizations).
--
-- In plain words:
--   * Sign-up no longer asks "demo data or own data". start_self_serve_trial() always starts the
--     free trial WITH the sample data and always on INR / Asia/Kolkata, whatever the browser
--     sends (an old cached page that still sends 'own' or a US time zone gets the same trial).
--     Same signature and grants, so the app keeps working while the new page loads.
--   * New nullable column organizations.trial_welcome_pending (the "show the 2-step welcome"
--     flag). start_self_serve_trial() sets it to true for the studio it has just created. The
--     dashboard asks my_trial_welcome_pending(), so the welcome (and then the tour) also shows
--     when the e-mail confirm link is opened on another device. trial_welcome_set(false) clears
--     it when the welcome is finished; trial_welcome_set(true) turns it on again (admin of a
--     studio on its free trial only). Existing studios stay NULL = no welcome.
--   * my_profile_status(): the admin of a studio ON its free trial (studio_subscriptions.status =
--     'trial', via _is_trial_org) is never forced to /profile-setup first: required = false, and
--     no profile nudge while the welcome is still pending. Invited members and paid studios:
--     unchanged (0041 rules).
--   No existing row is updated by this file. Additive + idempotent: add column if not exists,
--   create or replace. No DROP, DELETE or TRUNCATE. Safe to run twice.
-- ============================================================================

do $$ begin
  if to_regprocedure('public.start_self_serve_trial(text, text, text, text)') is null then
    raise exception '0180: start_self_serve_trial (0119) is missing'; end if;
  if to_regprocedure('public._is_trial_org(uuid)') is null then
    raise exception '0180: _is_trial_org (0166) is missing'; end if;
  if to_regprocedure('public._trial_locked(uuid)') is null then
    raise exception '0180: _trial_locked (0116) is missing'; end if;
  if to_regprocedure('public.my_profile_status()') is null or to_regprocedure('public._mp_is_operator()') is null then
    raise exception '0180: my_profile_status (0041) is missing'; end if;
  if to_regprocedure('public.tg_org_trial_india()') is null then
    raise exception '0180: the India trial trigger (0177) is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                 and table_name = 'organizations' and column_name = 'is_sample_master') then
    raise exception '0180: organizations.is_sample_master (0166) is missing'; end if;
end $$;

alter table public.organizations add column if not exists trial_welcome_pending boolean;
comment on column public.organizations.trial_welcome_pending is
  '0180: true = the free-trial owner has not finished the 2-step welcome yet (server-side, works across devices); NULL/false = no welcome';

-- ---- 1) the ONE self-serve free trial: always sample data, always India ------------------------
-- 0119 body; changed: p_mode / p_timezone / p_currency are accepted but ignored (always 'demo',
-- Asia/Kolkata, INR) and the new studio gets trial_welcome_pending = true.
create or replace function public.start_self_serve_trial(p_name text, p_timezone text, p_currency text, p_mode text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- unified-trial-0119 trial-signup-0180: always sample data + India; the welcome flag is set
declare
  v_uid uuid := auth.uid();
  v_tz text := 'Asia/Kolkata'; v_cur text := 'INR';
  v_mode text := 'demo';
  v_name text := nullif(btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')), '');
  v_had uuid; v_org uuid; v_n bigint; v_end timestamptz;
  v_seed jsonb; v_extra jsonb; o public.organizations;
begin
  if v_uid is null then raise exception 'must be signed in to start a trial' using errcode = '42501'; end if;
  -- already in a studio: hand it back, create / seed / change nothing
  select p.org_id into v_had from public.profiles p where p.id = v_uid;
  if v_had is not null then
    select * into o from public.organizations x where x.id = v_had;
    return jsonb_build_object('result', 'has_studio', 'org_id', v_had, 'name', o.name, 'trial_ends_at', o.trial_ends_at);
  end if;
  if coalesce(public.is_platform_admin(), false) then
    raise exception 'Helm operators do not get a studio' using errcode = '42501'; end if;
  if v_name is not null and (char_length(v_name) < 2 or char_length(v_name) > 80) then
    raise exception 'studio name must be 2 to 80 characters' using errcode = '22023'; end if;

  if v_name is null then
    -- one "Demo N" at a time across the whole database (same lock as 0116)
    perform pg_advisory_xact_lock(hashtextextended('helm:start_trial:demo_n', 0));
    v_n := public._trial_next_demo_number();
    v_name := 'Demo ' || v_n::text;
  end if;
  v_org := public.create_studio(v_name, null, v_cur, v_tz);
  select * into o from public.organizations x where x.id = v_org;
  -- never touch a studio this call did not just create
  if o.id is null or o.created_by is distinct from v_uid or o.trial_ends_at is not null then
    return jsonb_build_object('result', 'has_studio', 'org_id', v_org, 'name', o.name, 'trial_ends_at', o.trial_ends_at);
  end if;

  v_end := now() + make_interval(days => public._trial_days());
  -- the 0177 trigger stamps trial_region 'IN' and keeps INR / Asia/Kolkata / IN / GST on this update
  update public.organizations
     set trial_ends_at = v_end, trial_mode = v_mode, trial_welcome_pending = true
   where id = v_org and trial_ends_at is null;
  insert into public.studio_subscriptions(org_id, status, trial_ends_at, trial_source, updated_at, updated_by)
    values (v_org, 'trial', (v_end at time zone 'UTC')::date, 'bypass', now(), v_uid)
  on conflict (org_id) do nothing;

  -- sample data: a failure here never blocks the trial (that block alone is rolled back)
  begin v_seed := public._demo_seed(v_org);
  exception when others then v_seed := jsonb_build_object('seeded', false, 'error', sqlstate); end;
  begin v_extra := public._trial_seed_extra(v_org);
  exception when others then v_extra := jsonb_build_object('seeded', false, 'error', sqlstate); end;

  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    select v_uid, (select u.email from auth.users u where u.id = v_uid), 'subscription.trial_started',
           'organizations', v_org::text,
           jsonb_build_object('source', 'start_self_serve_trial', 'name', v_name, 'mode', v_mode,
                              'requested_mode', left(coalesce(p_mode, ''), 20),
                              'trial_ends_at', v_end, 'seed', v_seed, 'extra', v_extra),
           v_org, now();
  return jsonb_build_object('result', 'started', 'org_id', v_org, 'name', v_name, 'mode', v_mode,
                            'currency', v_cur, 'timezone', v_tz, 'welcome', true,
                            'trial_ends_at', v_end, 'trial_days', public._trial_days(), 'seed', v_seed, 'extra', v_extra);
end $$;
revoke all on function public.start_self_serve_trial(text, text, text, text) from public, anon;
grant execute on function public.start_self_serve_trial(text, text, text, text) to authenticated, service_role;

-- ---- 2) server-side welcome flag ---------------------------------------------------------------
-- true only for an admin of the caller's own studio that is ON its free trial (not locked, not the
-- sample master) and still has the flag set. Paid studios: always false, even with a stray flag.
create or replace function public.my_trial_welcome_pending()
returns boolean language sql stable security definer set search_path = '' as $$
  -- trial-signup-0180
  select coalesce((
    select o.trial_welcome_pending is true
      from public.organizations o
     where o.id = public.current_org_id()
       and not coalesce(o.is_sample_master, false)
       and coalesce(public.is_admin(), false)
       and public._is_trial_org(o.id)
       and not coalesce(public._trial_locked(o.id), false)), false);
$$;
revoke all on function public.my_trial_welcome_pending() from public, anon;
grant execute on function public.my_trial_welcome_pending() to authenticated;

-- false: the welcome is finished (Skip / Send invites). true: show it again (the trial owner
-- removed the samples and names the studio once more). Admin of the caller's own studio only;
-- turning it ON needs a studio on its free trial. A studio that never had the flag stays NULL.
create or replace function public.trial_welcome_set(p_pending boolean)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-signup-0180
declare v_org uuid := public.current_org_id(); v_want boolean := coalesce(p_pending, false); v_n int;
begin
  if auth.uid() is null or v_org is null or not coalesce(public.is_admin(), false) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if v_want and not (public._is_trial_org(v_org)
                     and not coalesce((select o.is_sample_master from public.organizations o where o.id = v_org), false)) then
    raise exception 'only a free-trial studio uses this welcome step' using errcode = '22023'; end if;
  update public.organizations o
     set trial_welcome_pending = v_want
   where o.id = v_org
     and o.trial_welcome_pending is distinct from v_want
     and (v_want or o.trial_welcome_pending is not null);
  get diagnostics v_n = row_count;
  return jsonb_build_object('result', 'ok', 'pending', v_want, 'changed', v_n > 0);
end $$;
revoke all on function public.trial_welcome_set(boolean) from public, anon;
grant execute on function public.trial_welcome_set(boolean) to authenticated;

-- ---- 3) profile gate: the free-trial owner goes to the welcome, not /profile-setup -------------
-- 0041 body; added: an admin of a studio on its free trial is never required (nudge only after
-- the welcome is done). Everyone else: the 0041 rules, unchanged.
create or replace function public.my_profile_status()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- member-profile-0041 trial-signup-0180
declare v_me uuid := auth.uid(); v_p record; v_complete boolean; v_cut timestamptz; v_new boolean;
begin
  if v_me is null then raise exception 'not authorized' using errcode = '42501'; end if;
  select p.org_id, p.role, p.full_name, p.created_at, m.phone into v_p
    from public.profiles p left join public.member_profiles m on m.user_id = p.id where p.id = v_me;
  if not found then return jsonb_build_object('complete', false, 'required', false, 'nudge', false); end if;
  v_complete := nullif(btrim(coalesce(v_p.full_name, '')), '') is not null and v_p.phone is not null;
  if v_complete or v_p.org_id is null or v_p.role = 'client' or public._mp_is_operator() then
    return jsonb_build_object('complete', v_complete, 'required', false, 'nudge', false);
  end if;
  if v_p.role = 'admin' and public._is_trial_org(v_p.org_id) then
    return jsonb_build_object('complete', false, 'required', false,
      'nudge', not coalesce((select o.trial_welcome_pending from public.organizations o where o.id = v_p.org_id), false));
  end if;
  select s.gate_cutoff into v_cut from public.member_profile_settings s where s.id;
  v_new := v_cut is not null and v_p.created_at >= v_cut;
  return jsonb_build_object('complete', false, 'required', v_new, 'nudge', not v_new);
end $$;
revoke all on function public.my_profile_status() from public, anon;
grant execute on function public.my_profile_status() to authenticated;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 column organizations.trial_welcome_pending (nullable boolean)', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'organizations' and column_name = 'trial_welcome_pending' and data_type = 'boolean' and is_nullable = 'YES')),
  ('02 start_self_serve_trial is the 0180 body (always demo + India, sets the welcome flag; under the 0186 wrapper once 0186 is in)', coalesce((select pg_get_functiondef(f) like '%trial-signup-0180%' and pg_get_functiondef(f) like '%trial_welcome_pending = true%'
       from coalesce(to_regprocedure('public.start_self_serve_trial__pre0186(text, text, text, text)'), to_regprocedure('public.start_self_serve_trial(text, text, text, text)')) f), false)),
  ('03 start_self_serve_trial no longer refuses own / no browser time zone or currency', coalesce((select pg_get_functiondef(to_regprocedure('public.start_self_serve_trial(text, text, text, text)')) not like '%choose demo or own%' and pg_get_functiondef(to_regprocedure('public.start_self_serve_trial(text, text, text, text)')) not like '%pg_timezone_names%'), false)),
  ('04 my_profile_status: trial owner via _is_trial_org (not trial_ends_at)', coalesce((select pg_get_functiondef(to_regprocedure('public.my_profile_status()')) like '%trial-signup-0180%' and pg_get_functiondef(to_regprocedure('public.my_profile_status()')) like '%_is_trial_org%' and pg_get_functiondef(to_regprocedure('public.my_profile_status()')) not like '%trial_ends_at%'), false)),
  ('05 welcome functions: signed-in users only', has_function_privilege('authenticated', 'public.my_trial_welcome_pending()', 'execute') and has_function_privilege('authenticated', 'public.trial_welcome_set(boolean)', 'execute') and not has_function_privilege('anon', 'public.my_trial_welcome_pending()', 'execute') and not has_function_privilege('anon', 'public.trial_welcome_set(boolean)', 'execute')),
  ('06 start trial / profile status: signed-in users only', has_function_privilege('authenticated', 'public.start_self_serve_trial(text, text, text, text)', 'execute') and not has_function_privilege('anon', 'public.start_self_serve_trial(text, text, text, text)', 'execute') and has_function_privilege('authenticated', 'public.my_profile_status()', 'execute') and not has_function_privilege('anon', 'public.my_profile_status()', 'execute')),
  ('07 all four are SECURITY DEFINER with an empty search_path', (select count(*) = 4 from pg_proc p where p.oid in (to_regprocedure('public.start_self_serve_trial(text, text, text, text)'), to_regprocedure('public.my_trial_welcome_pending()'), to_regprocedure('public.trial_welcome_set(boolean)'), to_regprocedure('public.my_profile_status()')) and p.prosecdef and p.proconfig @> array['search_path=""'])),
  ('08 no paid studio has the welcome flag on', not exists (select 1 from public.organizations o join public.studio_subscriptions s on s.org_id = o.id where o.trial_welcome_pending is true and s.status <> 'trial')),
  ('09 the India trigger (0177) is still in place', exists (select 1 from pg_trigger where tgrelid = 'public.organizations'::regclass and tgname = 'zzz_org_trial_india_0177' and not tgisinternal))
) v(item, ok) order by item;

-- ##########################################################################################
-- SECTION 08/16: APPLY-0181.sql
-- ##########################################################################################
-- APPLY-0181.sql - paste into the Supabase SQL editor (staging first, then production). Needs 0173 applied first.
-- Free-trial server guards. Affects FREE TRIAL studios only (studio_subscriptions.status = 'trial'); paid studios unchanged.
-- Additive + idempotent: 1 new table (trial_create_log, starts empty, RLS on, no app access), new helper / trigger
-- functions + triggers, 8 RPCs wrapped (originals kept as *__pre0181), my_trial_limits re-created (same shape).
-- No existing table, column or row is changed or removed. Safe to run twice.
-- Rollback note: see the ROLLBACK paragraph at the top of the migration below (manual, function/trigger level only; no data involved).
begin;
-- 0181_trial_guards.sql - CANONICAL forward-only.
-- REQUIRES 0173 (_tl173_trial_locked / _tl173_guard / my_trial_limits / zzzz_tl173_cap), 0166 (_is_trial_org),
--          0164 (_is_system_change), 0097 (is_demo + zz_a97_demo_flag_guard), 0088 (custom_field_defs),
--          0096 (studio_template_*), 0129 (event_reminder_settings_set), 0157 (privacy_pin_set / _reset),
--          0078 / 0092 (payment_reminder_send_now).
--
-- In plain words (FREE TRIAL studios only: _is_trial_org() = studio_subscriptions.status 'trial', never
-- trial_ends_at; a paid studio never reaches a new check; the sample master studio and Helm's own system
-- work (seed, clone, Clear sample data, migrations) are exempt, exactly as in 0173):
--   1  More settings are refused on the server in the trial (same-signature wrappers, originals kept as
--      <name>__pre0181 with no app grants): layout templates (studio_template_save / _set_archived /
--      _set_default / _duplicate), the team event-reminder days (event_reminder_settings_set), the privacy
--      PIN (privacy_pin_set / privacy_pin_reset) and "Send reminder now" to a client
--      (payment_reminder_send_now). Reading is unchanged: the sample layouts still load in the builder and
--      privacy_pin_status / privacy_pin_check still unlock with the default PIN.
--   2  Custom fields: a trial studio cannot add, change or remove custom field definitions (custom_field_defs).
--   3  Menu & catalog (dish_catalog, menu_templates, chair_types, plate_types): in the trial only prices
--      change (chair / plate price, a package's price per plate, and a package's dish list). Rename, switching
--      an item off / on and removing it (delete) are refused. A price change keeps a sample row a sample row
--      (is_demo stays true), so "Clear sample data" still removes it.
--   4  Creation cap = 2 created IN TOTAL per list (leads, events / quotes, inventory items, vendors, staff,
--      venues). New table trial_create_log remembers every own row a trial studio adds, so deleting a row
--      never frees a slot; every own row that still exists (soft-deleted, shelved, archived, inactive) counts
--      too. A restored row with an id that was already counted comes back without using a new slot.
--      my_trial_limits() reports the same numbers. The 0173 cap trigger stays (it can only be stricter-or-equal).
--   Nothing is deleted or rewritten: 1 new table (starts empty), new functions + triggers, 8 RPCs wrapped.
--   No DELETE / TRUNCATE / DROP of data. Safe to run twice (a re-run only re-creates the wrappers and
--   functions; triggers are added only when missing).
--   ROLLBACK (manual, only if ever needed; no data involved): for each wrapped f: drop function public.f(args);
--   alter function public.f__pre0181(args) rename to f; re-grant execute as before; drop the zzzz_tl181_*
--   triggers. trial_create_log can stay (nothing reads it then).

do $$ begin
  if to_regprocedure('public._tl173_trial_locked(uuid)') is null or to_regprocedure('public._tl173_guard()') is null then
    raise exception 'STOP: 0173 (trial lockdown) is not applied'; end if;
  if to_regprocedure('public._is_trial_org(uuid)') is null then raise exception 'STOP: 0166 (_is_trial_org) is not applied'; end if;
  if to_regprocedure('public._is_system_change()') is null then raise exception 'STOP: 0164 (_is_system_change) is not applied'; end if;
end $$;

-- ---- 4a) the creation log (bookkeeping only: ids, no personal data) --------------------------------
create table if not exists public.trial_create_log (
  org_id     uuid        not null,
  entity     text        not null,
  row_id     text        not null,
  created_at timestamptz not null default now(),
  primary key (org_id, entity, row_id)
);
alter table public.trial_create_log enable row level security;
revoke all on table public.trial_create_log from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on table public.trial_create_log from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on table public.trial_create_log from authenticated'; end if;
  -- the same read-only guard as every studio table (a row is only logged when its own insert passed it anyway)
  if to_regprocedure('public.tg_studio_read_only()') is not null
     and not exists (select 1 from pg_trigger where tgrelid = 'public.trial_create_log'::regclass and tgname = 'zzz_studio_read_only') then
    execute 'create trigger zzz_studio_read_only before insert or update or delete on public.trial_create_log for each row execute function public.tg_studio_read_only(''org_id'')';
  end if;
end $$;

-- own rows a trial studio has created IN TOTAL in one list: remembered in the log (deleted ones included)
-- + own rows that exist but are not in the log (made before 0181, or sample rows the studio adopted)
create or replace function public._tl181_used(p_org uuid, p_table text)
returns integer language plpgsql stable security definer set search_path = '' as $$
-- trial-guards-0181
declare n integer;
begin
  if p_org is null or p_table is null
     or p_table not in ('leads', 'quotes', 'inventory_items', 'vendors', 'crew_members', 'venues') then return 0; end if;
  execute format('select (select count(*) from public.trial_create_log l where l.org_id = $1 and l.entity = $2)::integer
                       + (select count(*) from public.%I x where x.org_id = $1 and not x.is_demo
                            and not exists (select 1 from public.trial_create_log l
                                             where l.org_id = $1 and l.entity = $2 and l.row_id = x.id::text))::integer', p_table)
    into n using p_org, p_table;
  return coalesce(n, 0);
end $$;

create or replace function public._tl181_tg_cap_check()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-guards-0181: 2 own rows created IN TOTAL per list in the free trial
begin
  if new.org_id is null or coalesce(new.is_demo, false) then return new; end if;
  if public._is_system_change() then return new; end if;
  if not public._tl173_trial_locked(new.org_id) then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:cap:' || tg_table_name || ':' || new.org_id::text, 0));
  -- a restored row (same id) that was already counted comes back without using a new slot
  if exists (select 1 from public.trial_create_log l
              where l.org_id = new.org_id and l.entity = tg_table_name and l.row_id = new.id::text) then
    return new;
  end if;
  if public._tl181_used(new.org_id, tg_table_name) >= 2 then
    raise exception 'Free trial limit reached (2). Upgrade to add more.' using errcode = '42501', hint = 'trial_cap';
  end if;
  return new;
end $$;

create or replace function public._tl181_tg_cap_log()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-guards-0181: remember the own row the trial studio just added (AFTER INSERT: only rows really saved)
begin
  if new.org_id is null or coalesce(new.is_demo, false) then return null; end if;
  if public._is_system_change() then return null; end if;
  if not public._tl173_trial_locked(new.org_id) then return null; end if;
  insert into public.trial_create_log(org_id, entity, row_id) values (new.org_id, tg_table_name, new.id::text)
    on conflict do nothing;
  return null;
end $$;

do $$ declare t text; begin
  foreach t in array array['leads', 'quotes', 'inventory_items', 'vendors', 'crew_members', 'venues'] loop
    if to_regclass('public.' || t) is null then continue; end if;
    if not exists (select 1 from pg_trigger where tgrelid = format('public.%I', t)::regclass and tgname = 'zzzz_tl181_cap') then
      execute format('create trigger zzzz_tl181_cap before insert on public.%I for each row execute function public._tl181_tg_cap_check()', t);
    end if;
    if not exists (select 1 from pg_trigger where tgrelid = format('public.%I', t)::regclass and tgname = 'zzzz_tl181_cap_log') then
      execute format('create trigger zzzz_tl181_cap_log after insert on public.%I for each row execute function public._tl181_tg_cap_log()', t);
    end if;
  end loop;
end $$;

-- what the app may show before the server refuses (same shape as 0173; "used" now counts in total)
create or replace function public.my_trial_limits()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-lockdown-0173 + trial-guards-0181
declare v_org uuid := public.current_org_id(); v_used jsonb := '{}'::jsonb; t text;
begin
  if auth.uid() is null or v_org is null then raise exception 'not authorized' using errcode = '42501'; end if;
  if not public._tl173_trial_locked(v_org) then return jsonb_build_object('trial', false); end if;
  foreach t in array array['leads', 'quotes', 'inventory_items', 'vendors', 'crew_members', 'venues'] loop
    v_used := v_used || jsonb_build_object(t, public._tl181_used(v_org, t));
  end loop;
  return jsonb_build_object('trial', true, 'cap', 2, 'used', v_used);
end $$;

-- ---- 3) menu & catalog: prices only ------------------------------------------------------------------
create or replace function public._tl181_tg_catalog_edit()
returns trigger language plpgsql set search_path = '' as $$
-- trial-guards-0181: SECURITY INVOKER on purpose (current_user = the app role). Only direct app edits are
-- checked; Helm's own functions (trial seed, clone, Clear sample data) still change these rows.
declare v_ok text[]; v_skip text[] := array['is_demo', 'updated_at', 'updated_by'];
begin
  if current_user not in ('anon', 'authenticated') or not public._tl173_trial_locked(old.org_id) then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'In the free trial you can change prices, but not remove menu or catalog items. Upgrade to change them.'
      using errcode = '42501', hint = 'trial_locked';
  end if;
  v_ok := case tg_table_name when 'menu_templates' then array['price_per_plate', 'dishes']
                             when 'dish_catalog' then array[]::text[]
                             else array['price'] end;
  if (to_jsonb(new) - v_ok - v_skip) is distinct from (to_jsonb(old) - v_ok - v_skip) then
    raise exception 'In the free trial you can change prices, but not rename, switch off or remove menu or catalog items. Upgrade to change them.'
      using errcode = '42501', hint = 'trial_locked';
  end if;
  -- a price change keeps a sample row a sample row (0097 marks a renamed sample row as the studio's own;
  -- nothing can be renamed here), so Clear sample data still removes it
  if coalesce((to_jsonb(old) ->> 'is_demo')::boolean, false) and not coalesce((to_jsonb(new) ->> 'is_demo')::boolean, true) then
    new := jsonb_populate_record(new, jsonb_build_object('is_demo', true));
  end if;
  return new;
end $$;

do $$ declare t text; begin
  foreach t in array array['dish_catalog', 'menu_templates', 'chair_types', 'plate_types'] loop
    if to_regclass('public.' || t) is not null
       and not exists (select 1 from pg_trigger where tgrelid = format('public.%I', t)::regclass and tgname = 'zzzz_tl181_catalog') then
      execute format('create trigger zzzz_tl181_catalog before update or delete on public.%I for each row execute function public._tl181_tg_catalog_edit()', t);
    end if;
  end loop;
end $$;

-- ---- 2) custom field definitions: not in the trial ------------------------------------------------
create or replace function public._tl181_tg_custom_fields()
returns trigger language plpgsql set search_path = '' as $$
-- trial-guards-0181: SECURITY INVOKER on purpose (current_user = the app role); Helm's own functions are not checked
declare v_org uuid;
begin
  if tg_op = 'DELETE' then v_org := old.org_id; else v_org := new.org_id; end if;
  if current_user in ('anon', 'authenticated') and public._tl173_trial_locked(v_org) then
    raise exception 'Custom fields are not part of the free trial. Upgrade to add your own fields.'
      using errcode = '42501', hint = 'trial_locked';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

do $$ begin
  if to_regclass('public.custom_field_defs') is not null
     and not exists (select 1 from pg_trigger where tgrelid = 'public.custom_field_defs'::regclass and tgname = 'zzzz_tl181_custom_fields') then
    create trigger zzzz_tl181_custom_fields before insert or update or delete on public.custom_field_defs
      for each row execute function public._tl181_tg_custom_fields();
  end if;
end $$;

-- ---- 1) wrapped RPCs (same pattern as 0173) ---------------------------------------------------------
do $$
declare
  f text; v_new boolean; v_old regprocedure; v_pre regprocedure; v_name text; v_args text; v_idargs text; v_ret text; v_call text; n int; g record;
begin
  foreach f in array array[
    'public.studio_template_save(uuid,jsonb)', 'public.studio_template_set_archived(uuid,boolean)',
    'public.studio_template_set_default(uuid,boolean)', 'public.studio_template_duplicate(uuid)',
    'public.event_reminder_settings_set(integer)',
    'public.privacy_pin_set(text,text)', 'public.privacy_pin_reset()',
    'public.payment_reminder_send_now(uuid)'] loop
    v_old := to_regprocedure(f);
    if v_old is null then continue; end if;
    select p.proname, pg_get_function_arguments(p.oid), oidvectortypes(p.proargtypes), pg_get_function_result(p.oid), p.pronargs
      into v_name, v_args, v_idargs, v_ret, n from pg_proc p where p.oid = v_old;
    v_pre := to_regprocedure(format('public.%I(%s)', v_name || '__pre0181', v_idargs));
    v_new := false;
    if v_pre is null then
      -- first run: keep the original under __pre0181 (its grants move with it), then build the wrapper
      execute format('alter function public.%I(%s) rename to %I', v_name, v_idargs, v_name || '__pre0181');
      v_new := true;
    end if;
    select string_agg('$' || i, ', ' order by i) into v_call from generate_series(1, greatest(n, 1)) i where i <= n;
    execute format($w$create or replace function public.%I(%s) returns %s language plpgsql volatile security definer set search_path = '' as $b$
-- trial-guards-0181: free trial check, then the original
begin
  perform public._tl173_guard();
  return public.%I(%s);
end $b$
$w$, v_name, v_args, v_ret, v_name || '__pre0181', coalesce(v_call, ''));
    -- grants (only when the wrapper is new; a re-run keeps what is there): wrapper = the original's
    -- grants; the kept original = definer / service role only
    continue when not v_new;
    execute format('revoke all on function public.%I(%s) from public', v_name, v_idargs);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function public.%I(%s) from anon', v_name, v_idargs); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function public.%I(%s) from authenticated', v_name, v_idargs); end if;
    for g in select distinct r.rolname from pg_proc p, lateral aclexplode(p.proacl) a join pg_roles r on r.oid = a.grantee
              where p.oid = to_regprocedure(format('public.%I(%s)', v_name || '__pre0181', v_idargs)) and a.privilege_type = 'EXECUTE'
                and r.rolname in ('anon', 'authenticated', 'service_role') loop
      execute format('grant execute on function public.%I(%s) to %I', v_name, v_idargs, g.rolname);
    end loop;
    execute format('revoke all on function public.%I(%s) from public', v_name || '__pre0181', v_idargs);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function public.%I(%s) from anon', v_name || '__pre0181', v_idargs); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function public.%I(%s) from authenticated', v_name || '__pre0181', v_idargs); end if;
  end loop;
end $$;

-- ---- privileges --------------------------------------------------------------------------------------
do $$
declare f text;
begin
  foreach f in array array['public._tl181_used(uuid,text)', 'public._tl181_tg_cap_check()', 'public._tl181_tg_cap_log()',
                           'public._tl181_tg_catalog_edit()', 'public._tl181_tg_custom_fields()', 'public.my_trial_limits()'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    grant execute on function public.my_trial_limits() to authenticated;
  end if;
end $$;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 8 RPCs wrapped (original kept)', (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname like '%\_\_pre0181') = 8),
  ('02 wrappers carry the trial check', (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and position('trial-guards-0181' in p.prosrc) > 0
       and to_regprocedure('public.' || p.proname || '__pre0181(' || oidvectortypes(p.proargtypes) || ')') is not null) = 8),
  ('03 kept originals not callable by the app', not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like '%\_\_pre0181'
       and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')))),
  ('04 wrappers still callable by signed-in users', has_function_privilege('authenticated', 'public.studio_template_save(uuid,jsonb)', 'execute')
       and has_function_privilege('authenticated', 'public.event_reminder_settings_set(integer)', 'execute')
       and has_function_privilege('authenticated', 'public.privacy_pin_set(text,text)', 'execute')
       and has_function_privilege('authenticated', 'public.payment_reminder_send_now(uuid)', 'execute')),
  ('05 cap check + log triggers on 6 tables', (select count(*) from pg_trigger where tgname = 'zzzz_tl181_cap') = 6
       and (select count(*) from pg_trigger where tgname = 'zzzz_tl181_cap_log') = 6),
  ('06 catalog prices-only trigger on 4 tables', (select count(*) from pg_trigger where tgname = 'zzzz_tl181_catalog') = 4),
  ('07 custom field trigger', exists (select 1 from pg_trigger where tgrelid = 'public.custom_field_defs'::regclass and tgname = 'zzzz_tl181_custom_fields')),
  ('08 trial_create_log: RLS on, no app access, read-only guard', coalesce((select relrowsecurity from pg_class where oid = to_regclass('public.trial_create_log')), false)
       and not has_table_privilege('authenticated', 'public.trial_create_log', 'select')
       and not has_table_privilege('anon', 'public.trial_create_log', 'select')
       and exists (select 1 from pg_trigger where tgrelid = to_regclass('public.trial_create_log') and tgname = 'zzz_studio_read_only')),
  ('09 helper / trigger functions not callable by the app', not has_function_privilege('authenticated', 'public._tl181_used(uuid,text)', 'execute')
       and not has_function_privilege('authenticated', 'public._tl181_tg_cap_check()', 'execute')
       and not has_function_privilege('authenticated', 'public._tl181_tg_cap_log()', 'execute')
       and not has_function_privilege('authenticated', 'public._tl181_tg_catalog_edit()', 'execute')
       and not has_function_privilege('authenticated', 'public._tl181_tg_custom_fields()', 'execute')),
  ('10 my_trial_limits callable by signed-in users, counts in total', has_function_privilege('authenticated', 'public.my_trial_limits()', 'execute')
       and position('_tl181_used' in (select prosrc from pg_proc where oid = to_regprocedure('public.my_trial_limits()'))) > 0),
  ('11 0173 still in place', (select count(*) from pg_trigger where tgname = 'zzzz_tl173_cap') = 6),
  ('12 trial studios affected: ' || (select count(*) from public.studio_subscriptions where status = 'trial')::text, true)
) v(item, ok) order by item;

-- ##########################################################################################
-- SECTION 09/16: APPLY-0182.sql
-- ##########################################################################################
-- APPLY-0182.sql - paste into the Supabase SQL editor (STAGING first; production only when the owner says go).
-- Run AFTER APPLY-0171.sql, APPLY-0175.sql and APPLY-0177.sql. Free trial: the layout builder prices items at the
-- owner's inventory rates (Round Table 500, LED Wall 5000, Stage Barrier 1000 ...; chair 100); the Kapoor Sangeet
-- sample event moves to chair 100; a sample dish / package / inventory row edited in a trial stays sample data.
-- Additive + idempotent: functions + config keys only, nothing deleted, safe to run twice (the 2nd run changes nothing).
begin;
-- 0182_trial_builder_prices.sql - CANONICAL forward-only. REQUIRES 0097 + 0156 + 0166..0171 (+ 0175 for v6).
--
-- In plain words:
--   I-11  The layout builder in a free trial priced items from its in-code defaults (Round Table 1500,
--         LED Wall 18000, Stage Barrier 9000 ...) instead of the owner's inventory rates (500 / 5000 / 1000).
--         The builder reads the studio's pricing config (app_config 'pricing': assetPrices + chairPrice).
--         1  The sample master studio gets assetPrices = the owner's 2026-10-18 rate for EVERY builder
--            item type (142, one per item in public/builder.js ASSETS) and chairPrice 100 (Chair (single)).
--         2  The published snapshot keeps assetPrices + chairPrice, so every NEW trial gets them.
--         3  Existing TRIAL studios cloned from the sample (subscription status trial right now) get
--            assetPrices / chairPrice only where they have none yet; their own edits are kept.
--         4  The Kapoor Family Sangeet sample event (master only) gets chairPrice 100 (was 45). The server
--            pricing engine (D8) re-prices it (452,530 -> 472,000) and its 2 sample milestones and the
--            simulated advance follow (30 % advance 141,600 paid + 70 % balance 330,400), only while they
--            still carry their 0171 values. No money moves; sample rows only.
--         5  A new sample manifest is published once (current + 1). Only NEW trials get it.
--         Steps 1, 4 and 5 run once (marker: the manifest note below), so later owner edits to the
--         master in the app are never overwritten by a re-run.
--   I-14  In a free trial, editing (for example renaming) a sample dish, menu package or inventory item
--         no longer turns it into an own row: it keeps is_demo = true, so "Clear demo data" still
--         removes it and it never counts toward the trial cap. Only rows already is_demo, in a studio
--         cloned from the sample (organizations.sample_batch_id set), whose subscription is trial right
--         now (_is_trial_org), edited by that studio's own member. Every other table, every paid studio
--         and every converted studio keep the 0097 rule (a renamed demo row is adopted as own).
--   No table or column is added or dropped. Nothing is deleted. ASCII only. Safe to run twice.
-- ============================================================================

do $$ begin
  if to_regprocedure('public._a97_tg_demo_flag_guard()') is null or to_regprocedure('public._a156_patch(regprocedure,text,text)') is null
     or to_regprocedure('public._is_trial_org(uuid)') is null or to_regclass('public.app_config') is null
     or to_regclass('public.helm_trial_seed_manifest') is null or to_regprocedure('public._sample_studio_settings(uuid)') is null then
    raise exception '0182 needs 0097 + 0156 + 0166 + 0167 + 0168 first'; end if;
end $$;

