     and not has_function_privilege('authenticated', 'public._trial_used_for_org(uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public._trial_extend_block(uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public._trial_email_fingerprint(text)', 'execute')
     and not has_function_privilege('authenticated', 'public.tg_trial_grant_0186()', 'execute')
     and not has_function_privilege('anon', 'public._trial_used(uuid,text,uuid)', 'execute')),
  ('11 e-mail fingerprint ignores case, +tag and Gmail dots',
     public._trial_email_fingerprint(' A.B+x@GMail.com ') = public._trial_email_fingerprint('ab@gmail.com')
     and public._trial_email_fingerprint('a.b@example.com') <> public._trial_email_fingerprint('ab@example.com')),
  ('12 the sample studio is never in the ledger', not exists (select 1 from public.trial_grants g
     join public.organizations o on o.id = g.org_id where o.is_sample_master))
) v(item, ok)
union all
select '0187 ' || item as item, ok from (values
  ('01 outbox guard also blocks an ended unpaid (read-only) trial',
     position('trial-outbound-0187' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public._sample_outbound_blocked(uuid,text)')), '')) > 0
     and position('_trial_locked' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public._sample_outbound_blocked(uuid,text)')), '')) > 0),
  ('02 outbox guard: internal only (not callable by the app)',
     not has_function_privilege('authenticated', 'public._sample_outbound_blocked(uuid,text)', 'execute')
     and not has_function_privilege('anon', 'public._sample_outbound_blocked(uuid,text)', 'execute')),
  ('03 outbox skip triggers in place (insert + retry to pending)',
     exists (select 1 from pg_trigger where tgrelid = 'public.comms_outbox'::regclass and tgname = 'zzzz_ts166_outbox_skip')
     and exists (select 1 from pg_trigger where tgrelid = 'public.comms_outbox'::regclass and tgname = 'zzzz_tb179_outbox_skip_upd')
     and exists (select 1 from pg_trigger where tgrelid = 'public.pkg_outbox'::regclass and tgname = 'zzzz_ts166_outbox_skip')),
  ('04 payment_link_begin wrapped (trial check, old body kept)',
     position('trial-outbound-0187' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.payment_link_begin(uuid,integer)')), '')) > 0
     and to_regprocedure('public.payment_link_begin__pre0187(uuid,integer)') is not null),
  ('05 payment_link_begin + kept body: service role only',
     has_function_privilege('service_role', 'public.payment_link_begin(uuid,integer)', 'execute')
     and not has_function_privilege('authenticated', 'public.payment_link_begin(uuid,integer)', 'execute')
     and not has_function_privilege('anon', 'public.payment_link_begin(uuid,integer)', 'execute')
     and not has_function_privilege('authenticated', 'public.payment_link_begin__pre0187(uuid,integer)', 'execute')
     and not has_function_privilege('anon', 'public.payment_link_begin__pre0187(uuid,integer)', 'execute')),
  ('06 no queued client message pending for an ended unpaid trial',
     not exists (select 1 from public.comms_outbox c where c.status = 'pending' and c.sent_at is null and public._trial_locked(c.org_id))
     and not exists (select 1 from public.pkg_outbox c where c.status = 'pending' and c.sent_at is null and public._trial_locked(c.org_id))),
  ('07 paid studios: never blocked',
     not exists (select 1 from public.studio_subscriptions s where s.status = 'active' and public._sample_outbound_blocked(s.org_id, null)))
) v(item, ok)
union all
select 'FIX-0177 no self-serve trial studio left off the India defaults' as item,
  not exists (
select o.id, o.name, o.currency, o.timezone, o.country, o.tax_region
  from public.organizations o
 where o.trial_ends_at is not null and o.trial_mode is not null and not coalesce(o.is_sample_master, false)
   and coalesce((select s.status from public.studio_subscriptions s where s.org_id = o.id), 'trial') = 'trial'
   and exists (select 1 from public.audit_log a where a.org_id = o.id and a.action = 'subscription.trial_started'
                 and a.changed ->> 'source' in ('start_self_serve_trial', 'start_trial', 'my_pending_start_trial'))
   and (o.currency <> 'INR' or o.timezone <> 'Asia/Kolkata' or o.country is distinct from 'IN' or o.trial_region is distinct from 'IN')
) as ok
union all
select 'REFRESH-0178 every trial studio on the current sample, India, 4 sample venues, no queued send' as item,
  not exists (select 1 from (
select o.id, o.name, o.sample_version, o.currency, o.timezone, o.country, o.tax_region,
       (select count(*) from public.venues v where v.org_id = o.id and v.is_demo and v.active and v.name like E'Demo \u00b7 %') as active_sample_venues,
       (select count(*) - count(distinct v.name) from public.venues v where v.org_id = o.id and v.is_demo and v.active) as dup_venues,
       (select count(*) from public.comms_outbox c where c.org_id = o.id and c.status = 'pending') as pending_outbox,
       ( o.sample_version = (select m.version from public.helm_trial_seed_manifest m where m.is_current) and o.currency = 'INR' and o.timezone = 'Asia/Kolkata' and o.country = 'IN'
         and (select count(*) from public.venues v where v.org_id = o.id and v.is_demo and v.active and v.name like E'Demo \u00b7 %') = 4
         and (select count(*) - count(distinct v.name) from public.venues v where v.org_id = o.id and v.is_demo and v.active) = 0
         and not exists (select 1 from public.comms_outbox c where c.org_id = o.id and c.status = 'pending') ) as ok
  from public.organizations o
  join public.studio_subscriptions s on s.org_id = o.id and s.status = 'trial'
 where o.id <> 'a5a5a5a5-0166-4000-8000-000000000001' and not coalesce(o.is_sample_master, false)
 order by ok, o.created_at
) z where not coalesce(z.ok, false)) as ok
order by 1;
